// Artwork composition + routes (artwork): the read-time `artwork` stamp on
// the served series/item DTOs — override → first non-placeholder poster
// walking the gate-resolved chain → absent (the omitempty then omitting the
// field) — the art object serve route, and the poster override family
// symmetric to titles. Composition mirrors the display-naming posture:
// batched per-page reads, tolerant (a corrupt document floors to absence,
// never fails the read), never persisted; the thumbnail leg stays
// client-side. All handlers and wire structs here are unexported — the api
// export budget stays untouched (the titles.go idiom).

package api

import (
	"context"
	"database/sql"
	"encoding/json"
	"errors"
	"io"
	"net/http"
	"net/url"
	"os"
	"strings"
	"time"

	"github.com/go-chi/chi/v5"

	"github.com/mellifera/mellifera/internal/art"
	"github.com/mellifera/mellifera/internal/store"
)

// The two art_overrides id spaces (the entity kinds the store partitions by)
// and the wire vocabulary pieces (artwork): a PUT selection is
// "src:<plugin_id>" | "user:art_<64hex>" | "thumb"; the STORED form keeps
// ONE token shape — a user: selection is stored as its bare art_<sha256>
// token (the ingest convention), src:/thumb verbatim.
const (
	artKindSeries = "series"
	artKindItem   = "item"

	artSelectionSrcPrefix  = "src:"
	artSelectionUserPrefix = "user:"
	artSelectionThumb      = "thumb"

	// artObjectPath is the served proxy-URL prefix the composition stamps
	// for materialized artwork — the object route below.
	artObjectPath = "/api/v1/art/object/"

	// maxArtUploadBytes is the api-side transport cap on one upload — the
	// SAME budget the art store's guard re-checks; ErrTooLarge from the
	// guard is the authoritative verdict, this reader cap is hygiene.
	maxArtUploadBytes = 8 << 20 // 8 MiB

	// missingArtPathPrefix is the walk-side copy of the missing-art prefix
	// rule (artwork D9): a poster URL whose path lives under a known
	// missing-art asset prefix is upstream's "no art" placeholder. The
	// shikimori write side drops such fields outright; the committed golden
	// fixture internal/api/testdata/golden/missing_art.json pins this
	// predicate against that copy (TestArtWalkSkipGolden), so one side
	// drifting alone fails its own suite.
	missingArtPathPrefix = "/assets/globals/missing"
)

// placeholderPoster reports whether u's PATH carries the missing-art asset
// prefix — the prefix rule, not an exact-URL list. A relative document URL
// (a row enriched before the write-side drop) parses to the same path as
// its absolute form. A mistyped URL is not a placeholder.
func placeholderPoster(u string) bool {
	parsed, err := url.Parse(u)
	if err != nil {
		return false
	}
	return strings.HasPrefix(parsed.Path, missingArtPathPrefix)
}

// artTokenSHA parses an art token — exactly "art_" + 64 lowercase hex — into
// its sha256 payload (the wire shape guard, mirroring the art package's own
// format guard): nothing but hex can name an object below the art dir.
func artTokenSHA(token string) (string, bool) {
	const prefix, hexLen = "art_", 64
	if len(token) != len(prefix)+hexLen || !strings.HasPrefix(token, prefix) {
		return "", false
	}
	sha := token[len(prefix):]
	for i := 0; i < len(sha); i++ {
		c := sha[i]
		if (c < '0' || c > '9') && (c < 'a' || c > 'f') {
			return "", false
		}
	}
	return sha, true
}

// ---- composition (the display.go seam) --------------------------------------

// artRow is one row's art input: the entity id and its raw document.
type artRow struct {
	id  string
	doc json.RawMessage
}

// posterRef is one usable namespace poster the chain walk found.
type posterRef struct {
	source string // the plugin id the namespace belongs to
	url    string // the stored poster URL
}

// usablePosters walks the gate-resolved source chain over one document,
// returning every usable namespace poster in walk order: present and
// non-placeholder — the missing-art predicate treats a placeholder as
// absent, so the walk continues past it. Gate-disabled namespaces are
// skipped exactly like the metadata projection. A corrupt document yields
// nil (tolerant floor).
func usablePosters(n namer, doc map[string]any) []posterRef {
	if len(n.chain) == 0 || doc == nil {
		return nil
	}
	sources, _ := doc["sources"].(map[string]any)
	var out []posterRef
	for _, b := range n.chain {
		if !b.Enabled {
			continue
		}
		ns, ok := sources[b.ID].(map[string]any)
		if !ok {
			continue
		}
		u, _ := ns["poster"].(string)
		if u == "" || placeholderPoster(u) {
			continue
		}
		out = append(out, posterRef{source: b.ID, url: u})
	}
	return out
}

// thumbFact reads the item document's frame-grabber thumbnail fact — the
// existence check a thumb candidate and a pinned thumb need ("" = no fact,
// nothing to show on either leg).
func thumbFact(doc map[string]any) string {
	sources, _ := doc["sources"].(map[string]any)
	fg, _ := sources["frame-grabber"].(map[string]any)
	p, _ := fg["thumbnail_path"].(string)
	return p
}

// itemThumbPath is the client-side thumb leg: the EXISTING media route's
// variant URL (the thumbnail stays client-side — composition only points at
// it, never resolves its bytes).
func itemThumbPath(itemID string) string {
	return "/items/" + itemID + "/media?variant=" + mediaVariantThumb
}

// resolveArtSelection maps one stored override selection onto its artwork
// value: an art token resolves to the object route's proxy URL immediately
// (the bytes are content-addressed; a vanished blob 404s there honestly),
// "thumb" to the item's media thumb variant while the frame-grabber fact
// exists, and "src:<ns>" to that namespace's poster — but ONLY while the
// namespace still walks the enabled chain with a usable poster: a pin whose
// namespace vanished (or whose poster is itself a placeholder) floors
// silently to the chain value while the override row is retained. final is
// a URL ready to serve; remote is a raw poster URL still needing the
// materialization check; both "" mean the floor applies. An unknown stored
// value floors — never errors the read.
func resolveArtSelection(sel, entityID string, isItem bool, n namer, doc map[string]any) (final, remote string) {
	if sha, ok := artTokenSHA(sel); ok {
		return artObjectPath + "art_" + sha, ""
	}
	if sel == artSelectionThumb {
		if isItem && thumbFact(doc) != "" {
			return itemThumbPath(entityID), ""
		}
		return "", ""
	}
	if ns, ok := strings.CutPrefix(sel, artSelectionSrcPrefix); ok {
		for _, p := range usablePosters(n, doc) {
			if p.source == ns {
				return "", p.url
			}
		}
	}
	return "", ""
}

// artworkFor resolves the `artwork` field for a page of rows (artwork D3):
// override → first non-placeholder chain poster → absent. TWO batched reads
// price the page — ONE ListArtOverrides for the stored selections, ONE
// Staged pass over the resolved winner URLs — never per-row probes. An
// unmaterialized winner serves its raw URL immediately while a background
// acquisition is handed off (non-blocking, D4; a placeholder is never
// resolved, so never handed off). A nil Deps.Art degrades to absence (the
// additive field simply omits); a store failure propagates (500 at the call
// site); a corrupt document floors to absence.
func (a *app) artworkFor(ctx context.Context, kind string, rows []artRow, n namer) (map[string]string, error) {
	out := make(map[string]string, len(rows))
	if a.deps.Art == nil || len(rows) == 0 {
		return out, nil
	}
	ids, kinds, sels, err := a.deps.Store.ListArtOverrides(ctx)
	if err != nil {
		return nil, err
	}
	stored := make(map[string]string, len(rows))
	for i, id := range ids {
		if kinds[i] == kind {
			stored[id] = sels[i]
		}
	}
	type pending struct {
		rowID, url string // a raw remote winner awaiting the staged check
	}
	var pendings []pending
	for _, row := range rows {
		doc := docMap(row.doc)
		final, remote := "", ""
		if sel := stored[row.id]; sel != "" {
			final, remote = resolveArtSelection(sel, row.id, kind == artKindItem, n, doc)
		}
		if final == "" && remote == "" {
			if p := usablePosters(n, doc); len(p) > 0 {
				remote = p[0].url
			}
		}
		switch {
		case final != "":
			out[row.id] = final
		case remote != "":
			pendings = append(pendings, pending{row.id, remote})
		}
		// else: absent — the omitempty omits
	}
	urls := make([]string, 0, len(pendings))
	for _, p := range pendings {
		urls = append(urls, p.url)
	}
	staged, err := a.deps.Art.Staged(ctx, urls, art.KindPoster)
	if err != nil {
		return nil, err
	}
	for _, p := range pendings {
		if token, ok := staged[p.url]; ok {
			out[p.rowID] = artObjectPath + token
		} else {
			out[p.rowID] = p.url
			a.deps.Art.Request(p.url, art.KindPoster)
		}
	}
	return out, nil
}

// ---- wire shapes (unexported — INV4) ----------------------------------------

// posterCandidate is one candidate card of GET …/posters (artwork): source
// is the bare plugin id for a namespace poster, "user" for the operator's
// upload, "thumb" for the frame-grabber variant; url is the SERVED proxy URL
// when the candidate is staged, the raw remote URL when it is not (the
// admin-only overlay's contractual exception); current marks the active
// selection.
type posterCandidate struct {
	Source  string `json:"source"`
	URL     string `json:"url"`
	Current bool   `json:"current"`
}

// posterCandidatesResponse is the GET …/posters envelope (artwork): the
// effective current selection in the PUT vocabulary ("" = the chain
// composes) plus the candidates.
type posterCandidatesResponse struct {
	Current    string            `json:"current"`
	Candidates []posterCandidate `json:"candidates"`
}

// posterSelectionRequest is the body of PUT …/poster (artwork): one
// selection from the vocabulary. The pointer carries presence so a missing
// field is rejected before any store call (the titleRequest precedent).
type posterSelectionRequest struct {
	Selection *string `json:"selection"`
}

// posterOverrideResponse is the wire shape of a stored poster override —
// the PUT/upload 200 body (the record as persisted; the titleOverrideDTO
// precedent).
type posterOverrideResponse struct {
	EntityID   string `json:"entity_id"`
	EntityKind string `json:"entity_kind"`
	Selection  string `json:"selection"`
	UpdatedAt  string `json:"updated_at"`
}

// ---- handlers ---------------------------------------------------------------

// artEntityRow is one loaded art entity: the row id, its library (the chain
// scope), and its raw document.
type artEntityRow struct {
	id        string
	libraryID int64
	doc       json.RawMessage
}

// loadArtEntity loads the series or item row an art route addresses — the
// existence check the read and mutating verbs share (a ghost is a wrapped
// sql.ErrNoRows → 404 at the call site, the title-override precedent).
func loadArtEntity(ctx context.Context, st *store.Store, kind, id string) (artEntityRow, error) {
	switch kind {
	case artKindSeries:
		sr, err := st.GetSeries(ctx, id)
		if err != nil {
			return artEntityRow{}, err
		}
		return artEntityRow{id: sr.ID, libraryID: sr.LibraryID, doc: sr.Document}, nil
	default:
		it, err := st.GetItem(ctx, id)
		if err != nil {
			return artEntityRow{}, err
		}
		return artEntityRow{id: it.ID, libraryID: it.LibraryID, doc: it.Document}, nil
	}
}

// parseArtSelection validates one PUT selection against the vocabulary and
// returns its STORED form: "src:<plugin_id>" and "thumb" verbatim, a
// "user:art_<64hex>" as its bare art_<sha256> token. ok=false on anything
// else — the caller answers 400 bad_request.
func parseArtSelection(sel string) (string, bool) {
	switch {
	case strings.HasPrefix(sel, artSelectionSrcPrefix) && len(sel) > len(artSelectionSrcPrefix):
		return sel, true
	case strings.HasPrefix(sel, artSelectionUserPrefix):
		sha, ok := artTokenSHA(strings.TrimPrefix(sel, artSelectionUserPrefix))
		if !ok {
			return "", false
		}
		return "art_" + sha, true
	case sel == artSelectionThumb:
		return sel, true
	}
	return "", false
}

// wireSelection renders a stored selection in the PUT vocabulary: the bare
// art_<sha256> token the store pins rides the wire as "user:art_<…>";
// src:/thumb pass through verbatim.
func wireSelection(sel string) string {
	if _, ok := artTokenSHA(sel); ok {
		return artSelectionUserPrefix + sel
	}
	return sel
}

// artObject serves one art object's bytes (artwork D5): pure path resolution
// from the oid — exactly art_<full-64-hex> — to the stored file, ZERO store
// reads and NEVER an upstream contact (a serve miss is a canonical 404,
// full stop). The strong ETag is the hex itself (content-addressed: the name
// is the validator), Cache-Control private+immutable (write-once bytes
// behind a bearer-authed route), and http.ServeContent answers HEAD,
// If-None-Match 304s, and Range for free. Nil-safe: 503 when Deps.Art is
// nil (the posture every Deps collaborator shares).
//
// @Summary      Serve an art object's bytes
// @Tags         art
// @ID           get-art-object
// @Router       /art/object/{oid} [get]
// @Param        oid path string true "art object id (art_<sha256 hex>)"
// @Success      200 {file} file
// @Failure      304 {string} string
// @Failure      404 {object} errorBody
// @Failure      503 {object} errorBody
func (a *app) artObject(w http.ResponseWriter, r *http.Request) {
	if a.deps.Art == nil {
		writeError(w, http.StatusServiceUnavailable, "unavailable", "art endpoint disabled", false)
		return
	}
	oid := chi.URLParam(r, "oid")
	if _, ok := artTokenSHA(oid); !ok {
		writeError(w, http.StatusNotFound, "not_found", "no art object "+oid, false)
		return
	}
	path, contentType, err := a.deps.Art.Resolve(oid)
	if err != nil {
		if errors.Is(err, os.ErrNotExist) {
			writeError(w, http.StatusNotFound, "not_found", "no art object "+oid, false)
			return
		}
		writeError(w, http.StatusInternalServerError, "internal_error", err.Error(), true)
		return
	}
	f, err := os.Open(path)
	if err != nil {
		writeError(w, http.StatusNotFound, "not_found", "no art object "+oid, false)
		return
	}
	defer f.Close()
	h := w.Header()
	h.Set("Content-Type", contentType)
	h.Set("ETag", `"`+oid[len("art_"):]+`"`)
	h.Set("Cache-Control", "private, immutable")
	// A zero modtime: the content address is the validator (the ETag), the
	// bytes are write-once. HEAD is answered headers-only, If-None-Match
	// 304s, and Range works — all ServeContent.
	http.ServeContent(w, r, path, time.Time{}, f)
}

// posters serves the poster family's read half (artwork): the effective
// current selection plus one candidate per usable namespace poster (the
// walk predicate excludes placeholders), plus "user" when the upload is the
// active selection, plus "thumb" for items carrying the frame-grabber fact
// — pointing at the existing media thumb variant. Staged candidates carry
// their served proxy URLs; unstaged the raw remote URL, with a non-blocking
// acquisition handoff so selecting one is instant.
func (a *app) posters(w http.ResponseWriter, r *http.Request, kind string) {
	if a.deps.Art == nil {
		writeError(w, http.StatusServiceUnavailable, "unavailable", "art endpoint disabled", false)
		return
	}
	row, err := loadArtEntity(r.Context(), a.deps.Store, kind, chi.URLParam(r, "id"))
	if err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			writeError(w, http.StatusNotFound, "not_found", kind+" "+chi.URLParam(r, "id")+" not found", false)
			return
		}
		writeError(w, http.StatusInternalServerError, "internal_error", err.Error(), true)
		return
	}
	sel, err := a.storedSelection(r.Context(), row.id, kind)
	if err != nil {
		writeError(w, http.StatusInternalServerError, "internal_error", err.Error(), true)
		return
	}
	n, err := a.namerFor(r.Context(), row.libraryID)
	if err != nil {
		writeError(w, http.StatusInternalServerError, "internal_error", err.Error(), true)
		return
	}
	doc := docMap(row.doc)
	refs := usablePosters(n, doc)
	urls := make([]string, 0, len(refs))
	for _, p := range refs {
		urls = append(urls, p.url)
	}
	staged, err := a.deps.Art.Staged(r.Context(), urls, art.KindPoster)
	if err != nil {
		writeError(w, http.StatusInternalServerError, "internal_error", err.Error(), true)
		return
	}
	cands := make([]posterCandidate, 0, len(refs)+2)
	for _, p := range refs {
		u := p.url
		if token, ok := staged[p.url]; ok {
			u = artObjectPath + token
		} else {
			a.deps.Art.Request(p.url, art.KindPoster)
		}
		cands = append(cands, posterCandidate{
			Source:  p.source,
			URL:     u,
			Current: sel == artSelectionSrcPrefix+p.source,
		})
	}
	if sha, ok := artTokenSHA(sel); ok {
		cands = append(cands, posterCandidate{
			Source:  "user",
			URL:     artObjectPath + "art_" + sha,
			Current: true,
		})
	}
	if kind == artKindItem && thumbFact(doc) != "" {
		cands = append(cands, posterCandidate{
			Source:  artSelectionThumb,
			URL:     itemThumbPath(row.id),
			Current: sel == artSelectionThumb,
		})
	}
	writeJSON(w, http.StatusOK, posterCandidatesResponse{
		Current:    wireSelection(sel),
		Candidates: cands,
	})
}

// storedSelection loads one entity's stored poster override, "" when none —
// the tolerant-lookup posture storedTitle uses (an absent row is no
// override, never an error beyond the sentinel).
func (a *app) storedSelection(ctx context.Context, entityID, kind string) (string, error) {
	sel, err := a.deps.Store.GetArtOverride(ctx, entityID, kind)
	if err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			return "", nil
		}
		return "", err
	}
	return sel, nil
}

// putPoster pins a selection from the vocabulary (artwork): validation is
// the parse step, BEFORE any store call — an unknown or malformed selection
// is 400 bad_request with nothing written, a ghost entity 404 not_found
// (the title-override precedent). A "user:art_<64hex>" selection is stored
// as its bare art_<sha256> token. Selecting a namespace candidate starts
// its acquisition (non-blocking; the fetch-once economics collapse it when
// already materialized). A metadata refresh never touches the row.
func (a *app) putPoster(w http.ResponseWriter, r *http.Request, kind string) {
	var req posterSelectionRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil || req.Selection == nil {
		writeError(w, http.StatusBadRequest, "bad_request", "malformed JSON body", false)
		return
	}
	stored, ok := parseArtSelection(*req.Selection)
	if !ok {
		writeError(w, http.StatusBadRequest, "bad_request",
			"selection must be src:<plugin_id>, user:art_<64hex>, or thumb", false)
		return
	}
	row, err := loadArtEntity(r.Context(), a.deps.Store, kind, chi.URLParam(r, "id"))
	if err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			writeError(w, http.StatusNotFound, "not_found", kind+" "+chi.URLParam(r, "id")+" not found", false)
			return
		}
		writeError(w, http.StatusInternalServerError, "internal_error", err.Error(), true)
		return
	}
	// The src handoff's chain scope, read BEFORE the write (validation-first:
	// a failing read writes nothing) and used after it succeeds. Selecting a
	// namespace candidate starts its acquisition (non-blocking; fetch-once
	// collapses it when already materialized; a vanished namespace starts
	// nothing and floors silently at composition).
	var handoff []string
	if ns, ok := strings.CutPrefix(stored, artSelectionSrcPrefix); ok {
		n, err := a.namerFor(r.Context(), row.libraryID)
		if err != nil {
			writeError(w, http.StatusInternalServerError, "internal_error", err.Error(), true)
			return
		}
		for _, ref := range usablePosters(n, docMap(row.doc)) {
			if ref.source == ns {
				handoff = append(handoff, ref.url)
			}
		}
	}
	stamp, err := a.deps.Store.UpsertArtOverride(r.Context(), row.id, kind, stored)
	if err != nil {
		writeError(w, http.StatusInternalServerError, "internal_error", err.Error(), true)
		return
	}
	if a.deps.Art != nil {
		for _, u := range handoff {
			a.deps.Art.Request(u, art.KindPoster)
		}
	}
	writeJSON(w, http.StatusOK, posterOverrideResponse{
		EntityID:   row.id,
		EntityKind: kind,
		Selection:  wireSelection(stored),
		UpdatedAt:  stamp,
	})
}

// uploadPoster ingests a multipart upload and pins it (artwork D6): the
// request body is capped at the transport layer (http.MaxBytesReader — the
// art store's guard re-checks the bytes authoritatively), the "file" part
// is delegated to art IngestBytes — the ONE image guard: magic sniff, ≤8
// MiB, real decode, then the crop-once 2:3 — and the pinned art_<sha256>
// token is the response's selection. Replacing an upload deletes the old
// pair (ingest semantics); a wrong type or an oversize body is a canonical
// 400 with nothing stored, no fetch row, no override change.
func (a *app) uploadPoster(w http.ResponseWriter, r *http.Request, kind string) {
	if a.deps.Art == nil {
		writeError(w, http.StatusServiceUnavailable, "unavailable", "art endpoint disabled", false)
		return
	}
	row, err := loadArtEntity(r.Context(), a.deps.Store, kind, chi.URLParam(r, "id"))
	if err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			writeError(w, http.StatusNotFound, "not_found", kind+" "+chi.URLParam(r, "id")+" not found", false)
			return
		}
		writeError(w, http.StatusInternalServerError, "internal_error", err.Error(), true)
		return
	}
	r.Body = http.MaxBytesReader(w, r.Body, maxArtUploadBytes)
	if err := r.ParseMultipartForm(1 << 20); err != nil {
		writeError(w, http.StatusBadRequest, "bad_request",
			"multipart form required with a file part under 8 MiB", false)
		return
	}
	file, _, err := r.FormFile("file")
	if err != nil {
		writeError(w, http.StatusBadRequest, "bad_request", "multipart form needs a file part named file", false)
		return
	}
	defer file.Close()
	body, err := io.ReadAll(file)
	if err != nil {
		writeError(w, http.StatusBadRequest, "bad_request", "upload bytes unreadable or over 8 MiB", false)
		return
	}
	token, err := a.deps.Art.IngestBytes(r.Context(), row.id, kind, body, art.KindPoster)
	if err != nil {
		if errors.Is(err, art.ErrNotImage) || errors.Is(err, art.ErrTooLarge) {
			writeError(w, http.StatusBadRequest, "bad_request", err.Error(), false)
			return
		}
		writeError(w, http.StatusInternalServerError, "internal_error", err.Error(), true)
		return
	}
	writeJSON(w, http.StatusOK, posterOverrideResponse{
		EntityID:   row.id,
		EntityKind: kind,
		Selection:  wireSelection(token),
		UpdatedAt:  "", // the upsert stamp the ingest pinned — re-read for the record
	})
}

// deletePoster resets to the chain (artwork): the override row is deleted
// idempotently — 204 every time, even for a ghost id. The blobs themselves
// are never touched here: the GC reclaims the unreferenced pair on its next
// pass (reference loss, never request-time deletion).
func (a *app) deletePoster(w http.ResponseWriter, r *http.Request, kind string) {
	if err := a.deps.Store.DeleteArtOverride(r.Context(), chi.URLParam(r, "id"), kind); err != nil {
		writeError(w, http.StatusInternalServerError, "internal_error", err.Error(), true)
		return
	}
	w.WriteHeader(http.StatusNoContent)
}

// ---- the ten route bindings (artwork) ---------------------------------------
// Thin wrappers over the shared handlers, each carrying its own swag
// annotation block so the OpenAPI contract lists every route with the right
// tags and operation ids (the titles.go idiom).

// @Summary      List an element's poster candidates
// @Tags         series
// @ID           list-series-posters
// @Router       /series/{id}/posters [get]
// @Param        id path string true "series id (ser_...)"
// @Success      200 {object} posterCandidatesResponse
// @Failure      404 {object} errorBody
// @Failure      503 {object} errorBody
